async function loadAddress(){try{const e=await fetch("/idn/address");if(!e.ok)throw new Error(`Response status: ${e.status}`);const t=await e.json();return t.data}catch(e){console.error("Error loading provinces, cities, and districts:",e)}}async function loadVillages(e){try{const t=await fetch(`/idn/villages/${e}`);return(await t.json()).data}catch(e){console.error("Error loading villages:",e)}}document.addEventListener("DOMContentLoaded",async function(){const e=document.getElementById("province"),t=document.getElementById("city"),n=document.getElementById("district"),i=document.getElementById("village"),a=await loadAddress(),o={province:e.dataset.selected||document.getElementById("init_province")?.value||e.value||"",city:t.dataset.selected||document.getElementById("init_city")?.value||t.value||"",district:n.dataset.selected||document.getElementById("init_district")?.value||n.value||"",village:i.dataset.selected||document.getElementById("init_village")?.value||i.value||""};function d(e,d=""){if(t.innerHTML='<option value="">Pilih Kota/Kabupaten</option>',n.innerHTML='<option value="">Pilih Kecamatan</option>',i.innerHTML='<option value="">Pilih Kelurahan/Desa</option>',!e)return;a.cities.filter(t=>String(t.province_id)==String(e)).forEach(e=>t.add(new Option(e.name,e.id))),d&&(t.value=d,c(d,o.district))}function c(e,t=""){if(n.innerHTML='<option value="">Pilih Kecamatan</option>',i.innerHTML='<option value="">Pilih Kelurahan/Desa</option>',!e)return;a.districts.filter(t=>String(t.regency_id)==String(e)).forEach(e=>n.add(new Option(e.name,e.id))),t&&(n.value=t,l(t,o.village))}async function l(e,t=""){if(i.innerHTML='<option value="">Pilih Kelurahan/Desa</option>',!e)return;(await loadVillages(e)||[]).forEach(e=>i.add(new Option(e.name,e.id))),t&&(i.value=t)}a.provinces.forEach(t=>{const n=new Option(t.name,t.id);e.add(n)});document.getElementById("zipcode").addEventListener("input",function(){this.value=this.value.replace(/\D/g,"").substr(0,5),5===this.value.length?this.classList.remove("is-invalid"):this.classList.add("is-invalid")}),o.province&&(e.value=o.province,d(o.province,o.city)),e.addEventListener("change",async function(){d(this.value)}),t.addEventListener("change",async function(){c(this.value)}),n.addEventListener("change",async function(){await l(this.value)})});